const dialog=document.querySelector('#project-dialog');let lastTrigger;
function openProject(i){lastTrigger=document.activeElement;const p=projects[i];document.querySelector('#dialog-content').innerHTML=`<p class="eyebrow">${String(i+1).padStart(2,'0')} / ${p.category}</p><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p>${p.contribution?`<h3>${i===6?'Project context':'My contribution'}</h3><p>${p.contribution}</p>`:''}<div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>${p.url?`<a class="text-link" href="${p.url}" target="_blank" rel="noopener noreferrer">Explore the code <span aria-hidden="true">↗</span></a>`:''}${p.note?`<p class="project-note">${p.note}</p>`:''}`;dialog.showModal();dialog.scrollTop=0;document.querySelector('.dialog-close').focus()}
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>lastTrigger?.focus());
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
function updateRail(){const step=rail.children[0].getBoundingClientRect().width+parseFloat(getComputedStyle(rail).gap);const start=Math.round(rail.scrollLeft/step);const visible=Math.max(1,Math.floor((rail.clientWidth+22)/step));document.querySelector('#project-position').textContent=`${String(start+1).padStart(2,'0')}—${String(Math.min(6,start+visible)).padStart(2,'0')}`;document.querySelector('#prev-project').disabled=rail.scrollLeft<5;document.querySelector('#next-project').disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-5}
function advance(direction){const step=rail.children[0].getBoundingClientRect().width+parseFloat(getComputedStyle(rail).gap);rail.scrollBy({left:direction*step,behavior:reduced.matches?'instant':'smooth'})}
document.querySelector('#prev-project').addEventListener('click',()=>advance(-1));document.querySelector('#next-project').addEventListener('click',()=>advance(1));rail.addEventListener('scroll',updateRail,{passive:true});window.addEventListener('resize',updateRail);updateRail();document.querySelector('#year').textContent=new Date().getFullYear();
// Original particle sculpture. No ThreeUI source or external rendering dependency.
const canvas=document.querySelector('#particles'),ctx=canvas.getContext('2d');let width=0,height=0,paused=reduced.matches,visible=true,frame=0,time=0,last=0;const pointer={x:0,y:0};
const points=Array.from({length:4200},(_,i)=>{const a=i*2.399963229728653,r=Math.sqrt((i+.5)/4200);return{a,r,seed:Math.sin(i*127.1)*.5+.5}});
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(window.devicePixelRatio||1,1.75);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0);if(paused)draw()}
function draw(){if(!ctx)return;ctx.clearRect(0,0,width,height);const mobile=width<620,cx=width*(mobile?.83:.74),cy=height*(mobile?.55:.44),scale=Math.min(width*(mobile?.67:.33),height*.52),angle=time*.12+pointer.x*.12;const halo=ctx.createRadialGradient(cx,cy,0,cx,cy,scale*1.2);halo.addColorStop(0,'rgba(121,143,104,0.075)');halo.addColorStop(1,'rgba(121,143,104,0)');ctx.fillStyle=halo;ctx.fillRect(0,0,width,height);const stride=mobile?2:1;for(let i=0;i<points.length;i+=stride){const p=points[i],v=p.r*Math.PI,u=p.a;const wave=1+.2*Math.sin(u*3+v*5+time*.23)+.13*Math.cos(v*9-time*.17);let x=Math.sin(v)*Math.cos(u)*wave,y=Math.cos(v)*1.17,z=Math.sin(v)*Math.sin(u)*wave;const twist=y*.8+angle;const xx=x*Math.cos(twist)+z*Math.sin(twist),zz=-x*Math.sin(twist)+z*Math.cos(twist);y+=.10*Math.sin(u*4+time*.2);const perspective=3.5/(3.5+zz);const px=cx+xx*scale*perspective+pointer.x*9,py=cy+(y+pointer.y*.045)*scale*perspective;const alpha=(.18+(zz+1.5)/3*.66)*(mobile?.45:1);ctx.fillStyle=`rgba(${199+Math.round(p.seed*35)},${204+Math.round(p.seed*30)},${178+Math.round(p.seed*30)},${alpha})`;ctx.beginPath();ctx.arc(px,py,(.45+p.seed*.65)*perspective,0,Math.PI*2);ctx.fill()}}
function tick(ts){frame=0;if(paused||!visible||document.hidden)return;if(ts-last>30){time+=Math.min((ts-last)/1000,.05);last=ts;draw()}frame=requestAnimationFrame(tick)}
function start(){if(!frame&&!paused&&visible&&!document.hidden){last=performance.now();frame=requestAnimationFrame(tick)}}
const motionButton=document.querySelector('#motion-toggle');function syncMotion(){motionButton.setAttribute('aria-pressed',String(paused));motionButton.setAttribute('aria-label',paused?'Play background animation':'Pause background animation');motionButton.innerHTML=`<span aria-hidden="true">${paused?'▷':'Ⅱ'}</span><span class="motion-label">${paused?'Play motion':'Pause motion'}</span>`;if(paused){cancelAnimationFrame(frame);frame=0;draw()}else start()}
motionButton.addEventListener('click',()=>{paused=!paused;syncMotion()});reduced.addEventListener('change',e=>{paused=e.matches;syncMotion()});document.querySelector('.hero').addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/width-.5;pointer.y=(e.clientY-r.top)/height-.5});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else{cancelAnimationFrame(frame);frame=0}}).observe(canvas);document.addEventListener('visibilitychange',start);window.addEventListener('resize',resize);resize();draw();syncMotion();
